def fib(n):                 # O(2ⁿ)：每次呼叫又分成兩次呼叫
    return n if n < 2 else fib(n - 1) + fib(n - 2)

def bubble_sort(arr):
    n = len(arr)
    for i in range(n):
        swapped = False
        for j in range(n - 1 - i):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:      # 一輪都沒交換，代表已經排好，提前結束
            break

def total(nums):            # 額外空間 O(1)
    result = 0              # 只多了一個變數
    for x in nums:
        result += x
    return result

def doubled(nums):          # 額外空間 O(n)
    return [x * 2 for x in nums]   # 多建了一個長度 n 的新串列

def factorial(n):
    if n <= 1:
        return 1
    return n * factorial(n - 1)
